function calculateTotal() {
    // Bills
    const hundredValue = parseInt(document.getElementById("hundred").value) * 100;
    const fiftyValue = parseInt(document.getElementById("fifty").value) * 50;
    const twentyValue = parseInt(document.getElementById("twenty").value) * 20;
    const tenValue = parseInt(document.getElementById("ten").value) * 10;
    const fiveValue = parseInt(document.getElementById("five").value) * 5;
    
    // Coins
    const Twoonie = parseInt(document.getElementById("Twoonies").value * 2);
    const Loonie = parseInt(document.getElementById("Loonies").value);
    const quartersValue = parseInt(document.getElementById("Quarters").value) * 0.25;
    const Dimes = parseInt(document.getElementById("Dimes").value) * 0.10;
    const nickelsValue = parseInt(document.getElementById("Nickels").value) * 0.05;
   
    // Calculate total
    const totalAmount = hundredValue + fiftyValue + twentyValue + tenValue + fiveValue + Twoonie +Loonie + quartersValue + Dimes + nickelsValue;

    // Display total
    document.getElementById("totalAmount").textContent = totalAmount.toFixed(2);
}
// Define an object to map coin IDs to their names
const coinNames = {
    Twoonies: "Twoonies",
    Loonies: "Loonies",
    Quarters: "Quarters",
    Dimes: "Dimes",
    Nickels: "Nickels"
};

// Initialize an array to store coins that need to be displayed
const lowCoins = [];

// Function to check coin values and update the display
function checkCoinValue() {
    // Loop through each coin ID
    for (const coinId in coinNames) {
        const coinValue = parseInt(document.getElementById(coinId).value);
        const coinName = coinNames[coinId];

        if (coinValue <= 9) {
            // Add coin to the list if value is less than or equal to 9
            if (!lowCoins.includes(coinName)) {
                lowCoins.push(coinName);
            }
        } else {
            // Remove coin from the list if value is greater than 9
            const index = lowCoins.indexOf(coinName);
            if (index !== -1) {
                lowCoins.splice(index, 1);
            }
        }
    }

    const messageSpan = document.getElementById("CoinsMessage");
    
    if (lowCoins.length > 0) {
        messageSpan.textContent = `Please request more ${lowCoins.join(", ")}.`;
    } else {
        messageSpan.textContent = ""; // Clear the message if all values are valid
    }
}

function copyToClipboard() {
    const el = document.createElement('textarea');  // Create a <textarea> element
    const copiedValue = document.getElementById('totalAmount').textContent;
    el.value = copiedValue;  // Set its value to the content you want copied
    document.body.appendChild(el);  // Add it to the document
    el.select();  // Select its content
    document.execCommand('copy');  // Copy it!
    document.body.removeChild(el);  // Remove the <textarea> element
    alert(`Total of $${copiedValue} copied to clipboard!`);  // Notify the user with the copied value
}
